#!/usr/bin/env python3
"""Раздел 2 «Проектирование и конструирование программного средства» в оформлении образца записки.

Шаблон: docs/kursovaya/src/template-oformlenie.docx (стили, поля, нумерация и колонтитулы образца, без текста).
Правила образца: обычный абзац – Times New Roman 14, одинарный интервал, отступ 1,25 см, по ширине;
после заголовка и перед заголовком подраздела пустая строка; рисунок на всю ширину текста (16,5 см),
пустые строки до и после рисунка и после подписи; подпись «Рисунок 2.1 – …» по центру;
формула отдельной строкой по центру (Word, OMML) после слов «по формуле:», за ней абзац «где …»
без отступа, обозначения набраны формулами; перечисления – стиль «List Paragraph» с маркером-тире.
Использование: python3 build_2.py [выход.docx]
"""
import json, os, sys
import docx
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.oxml import parse_xml
from docx.shared import Cm, Twips
from PIL import Image

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
KURS = os.path.join(ROOT, 'docs', 'kursovaya')
W = 'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"'
M = 'xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math"'
TEXT_W = 16.5          # ширина текста и рисунков, см (как в образце)
LAY_PATH = os.path.join(KURS, 'src', 'layout-2.json')
LAYOUT = json.load(open(LAY_PATH, encoding='utf-8')) if os.path.exists(LAY_PATH) else {}
REF = {
    'func': 'Функциональная архитектура программного средства показана на рисунке {n}.',
    'security': 'Уровни защиты показаны на рисунке {n}.',
    'arch': 'Путь запроса через слои модуля показан на рисунке {n}.',
    'transfer': 'Схема алгоритма представлена на рисунке {n}.',
    'loans': 'Схема алгоритма представлена на рисунке {n}.',
    'deposits': 'Схема алгоритма представлена на рисунке {n}.',
    'cabinet': 'Главная страница кабинета клиента показана на рисунке {n}.',
    'transfer-ui': 'Форма перевода показана на рисунке {n}.',
    'deposit-ui': 'Страница оформления вклада показана на рисунке {n}.',
    'statement': 'Выписка по счёту показана на рисунке {n}.',
    'workplace': 'Рабочее место операциониста показано на рисунке {n}.',
    'loan-review': 'Карточка заявки на кредит у кредитного специалиста показана на рисунке {n}.',
}


# ---------- формулы (OMML) ----------
def r(t):
    t = t.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')
    return f'<m:r><m:t xml:space="preserve">{t}</m:t></m:r>'


def frac(a, b):
    return f'<m:f><m:num>{a}</m:num><m:den>{b}</m:den></m:f>'


def sup(a, b):
    return f'<m:sSup><m:e>{a}</m:e><m:sup>{b}</m:sup></m:sSup>'


def sub(a, b):
    return f'<m:sSub><m:e>{a}</m:e><m:sub>{b}</m:sub></m:sSub>'


def paren(a):
    return f'<m:d><m:e>{a}</m:e></m:d>'


class Doc:
    def __init__(self, chap=2, layout=None, ref=None):
        self.d = docx.Document(os.path.join(KURS, 'src', 'template-oformlenie.docx'))
        self.chap = chap
        self.layout = LAYOUT if layout is None else layout
        self.ref = REF if ref is None else ref
        self.fig = 0
        self.eq = 0
        self.tab = 0

    def _p(self, style='Normal'):
        return self.d.add_paragraph(style=self.d.styles[style])

    def empty(self, style='Normal'):
        return self._p(style)

    def text(self, t, style='Normal'):
        p = self._p(style)
        p.paragraph_format.first_line_indent = Cm(1.25)
        p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        p.add_run(t)
        return p

    def h1(self, num, title):
        self._p('Heading 1').add_run(f'{num}\t{title.upper()}')
        self.empty()

    def h2(self, title, first=False):
        if not first:
            self.empty()
        h = self._p('Heading 2')
        h.paragraph_format.keep_with_next = True
        h.add_run(title)
        # пустая строка после заголовка тоже держится со следующим абзацем: заголовок не останется внизу страницы
        self.empty().paragraph_format.keep_with_next = True

    def bullets(self, items):
        for i, t in enumerate(items):
            p = self._p('List Paragraph')
            ppr = p._p.get_or_add_pPr()
            ppr.append(parse_xml(f'<w:numPr {W}><w:ilvl w:val="0"/><w:numId w:val="22"/></w:numPr>'))
            ppr.append(parse_xml(f'<w:tabs {W}><w:tab w:val="left" w:pos="993"/></w:tabs>'))
            p.paragraph_format.left_indent = Cm(0)
            p.paragraph_format.first_line_indent = Cm(1.25)
            p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
            end = '.' if i == len(items) - 1 else ';'
            p.add_run(t + end)

    def figure(self, name, caption, max_h=21.5, scale=1.0):
        """Рисунок на ширину текста (scale < 1 – уменьшение для вёрстки); пустые строки вокруг, подпись по центру."""
        self.fig += 1
        path = os.path.join(KURS, name)
        im = Image.open(path)
        w = TEXT_W
        # скриншоты сценариев: один масштаб для всех (ширина окна браузера = ширина текста), узкие карточки не растягиваются
        if getattr(self, 'px_full', None) and os.path.basename(name).startswith(('fig-test-', 'fig-guide-')) and name not in ('fig-test-run.png', 'fig-guide-install.png'):
            w = min(TEXT_W, TEXT_W * im.width / self.px_full)
        h = w * im.height / im.width
        max_h *= scale
        if scale < 1 and h <= max_h:
            w *= scale
            h *= scale
        if h > max_h:
            h = max_h
            w = h * im.width / im.height
        self.empty('No Spacing')
        p = self._p('No Spacing')
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        p.paragraph_format.keep_with_next = True
        p.add_run().add_picture(path, width=Cm(w), height=Cm(h))
        self.empty('No Spacing').paragraph_format.keep_with_next = True
        c = self._p('No Spacing')
        c.alignment = WD_ALIGN_PARAGRAPH.CENTER
        c.add_run(f'Рисунок {self.chap}.{self.fig} – {caption}')
        self.empty('No Spacing')
        return self.fig

    def unit(self, key, paras, name, caption):
        """Блок «текст + рисунок». Ссылка «рисунок 2.N» дописывается в абзац перед рисунком.
        Раскладка из layout-2.json: mode after – первый абзац, рисунок, остальные абзацы;
        mode before – все абзацы, затем рисунок; число – рисунок после стольких абзацев; scale – уменьшение рисунка."""
        lay = self.layout.get(key, {})
        mode, scale = lay.get('mode', 'after'), lay.get('scale', 1.0)
        n = self.fig + 1
        cut = 1 if mode == 'after' else len(paras) if mode == 'before' else min(int(mode), len(paras))
        for i, t in enumerate(paras[:cut]):
            self.text(t + (f' {self.ref[key].format(n=f"{self.chap}.{n}")}' if i == cut - 1 else ''))
        self.figure(name, caption, scale=scale)
        for t in paras[cut:]:
            self.text(t)

    def formula(self, omml):
        """Формула отдельной строкой с номером у правого края: в Word это запись «формула#(2.N)»
        (массив уравнений eqArr, знак # отделяет номер). Пустые строки до и после формулы."""
        self.eq += 1
        num = f'{self.chap}.{self.eq}'
        self.empty('No Spacing')
        p = self._p('No Spacing')
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        p._p.append(parse_xml(
            f'<m:oMathPara {M} {W}><m:oMath><m:eqArr><m:eqArrPr><m:maxDist m:val="1"/></m:eqArrPr><m:e>'
            f'{omml}{r("#")}<m:d><m:e>{r(num)}</m:e></m:d></m:e></m:eqArr></m:oMath></m:oMathPara>'))
        self.empty('No Spacing')
        return num

    def where(self, parts):
        """Расшифровка: «где X – …;» без отступа, каждое следующее обозначение – отдельной строкой точно под первым."""
        for i, (sym, expl) in enumerate(parts):
            p = self._p('No Spacing')
            p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
            if i == 0:
                p.add_run('где ')
            else:
                # ширина «где » в Times New Roman 14 пт: обозначение стоит точно под первым
                p.paragraph_format.left_indent = Twips(438)
            p._p.append(parse_xml(f'<m:oMath {M}>{sym}</m:oMath>'))
            p.add_run(f' – {expl}' + ('.' if i == len(parts) - 1 else ';'))

    def table(self, title, header, rows, widths_cm, center_cols=()):
        """Таблица как в образце: подпись «Таблица N.M – …» над таблицей (выступ 3 см), сетка, шрифт 14,
        шапка по центру и повторяется на каждой странице, строки не разрываются; после таблицы пустая строка."""
        self.tab += 1
        cap = self._p('Normal')
        cap.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
        cap.paragraph_format.left_indent = Cm(3)
        cap.paragraph_format.first_line_indent = Cm(-3)
        cap.paragraph_format.keep_with_next = True
        cap.add_run(f'Таблица {self.chap}.{self.tab} – {title}')
        t = self.d.add_table(rows=1 + len(rows), cols=len(header))
        t.style = self.d.styles['Table Grid']
        t.autofit = False
        # ширины колонок и в сетке таблицы (её читает LibreOffice), и в ячейках (их читает Word)
        tblPr = t._tbl.tblPr
        tblPr.append(parse_xml(f'<w:tblW {W} w:w="{int(sum(widths_cm) * 567)}" w:type="dxa"/>'))
        tblPr.append(parse_xml(f'<w:tblLayout {W} w:type="fixed"/>'))
        for gc, wcm in zip(t._tbl.tblGrid.findall('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}gridCol'), widths_cm):
            gc.set('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}w', str(int(wcm * 567)))
        for i, row in enumerate([header] + rows):
            tr = t.rows[i]._tr.get_or_add_trPr()
            tr.append(parse_xml(f'<w:cantSplit {W}/>'))
            if i == 0:
                tr.append(parse_xml(f'<w:tblHeader {W}/>'))
            for j, v in enumerate(row):
                c = t.rows[i].cells[j]
                c.width = Cm(widths_cm[j])
                p = c.paragraphs[0]
                p.style = self.d.styles['Normal']
                p.paragraph_format.first_line_indent = Cm(0)
                p.alignment = WD_ALIGN_PARAGRAPH.CENTER if i == 0 or j in center_cols else WD_ALIGN_PARAGRAPH.LEFT
                if i == 0:
                    p.paragraph_format.keep_with_next = True
                p.add_run(v)
        self.empty()
        return self.tab

    def save(self, out):
        self.d.save(out)


def build(out):
    b = Doc()
    b.h1(2, 'Проектирование и конструирование программного средства')

    # 2.1 ------------------------------------------------------------------
    b.h2('2.1 Постановка задачи', first=True)
    b.text('Целью разработки является программное средство дистанционного банковского обслуживания физических лиц «ТалерБанк» – веб-приложение, через которое клиент управляет своими счетами и банковскими продуктами, а сотрудники банка выполняют операционную работу. Приложение работает в браузере без установки на компьютер пользователя и обслуживает четыре категории пользователей. Это гость, клиент, сотрудники банка (операционист, кредитный специалист, специалист по финансовому мониторингу) и администратор.')
    b.text('Программное средство должно обеспечивать выполнение следующих операций:')
    b.bullets([
        'регистрацию клиента с проверкой анкеты операционистом и открытием первого текущего счёта',
        'открытие и закрытие счетов в пяти валютах с номером в формате IBAN',
        'переводы между своими счетами с конвертацией, переводы другим клиентам банка и в другие банки через клиринг с суточным лимитом и подтверждением одноразовым кодом',
        'оплату услуг по каталогу, шаблоны платежей и автоплатежи',
        'оформление вкладов с расчётом дохода, начисление процентов и досрочное закрытие с перерасчётом',
        'выдачу кредитов со скорингом заявки и графиком платежей, плановое списание платежей, пеню при просрочке и досрочное погашение',
        'выпуск, блокировку и закрытие платёжных карт, установку лимитов',
        'выписку по счёту, справку об остатке и квитанции в формате PDF',
        'контроль подозрительных переводов с задержкой операции до решения специалиста',
        'администрирование, включающее курсы и тарифы, пользователей и роли, журнал аудита, отчёты, резервное копирование и закрытие операционного дня',
    ])
    b.text('Входными данными являются анкеты клиентов, реквизиты операций, вводимые в формах, курсы валют Национального банка и настройки тарифов. Выходными данными являются проводки и документы в базе данных, ответы программного интерфейса в формате JSON, уведомления пользователям, документы PDF и отчёты.')
    b.text('Все денежные суммы хранятся и обрабатываются в копейках целыми числами, операции датируются банковской датой, которую сдвигает только закрытие операционного дня. Интерфейс выполняется на русском языке и должен работать в браузерах Яндекс Браузер, Firefox, Chrome и Opera в среде Windows 10 и новее.')

    # 2.2 ------------------------------------------------------------------
    b.h2('2.2 Обоснование выбора технологий разработки')
    b.text('Серверная часть выполнена на платформе Node.js 22 с каркасом Express 5. Выбор определяется требованием задания вести бизнес-логику на языке JavaScript. Платформа Node.js позволяет использовать один язык на сервере и на клиенте, что упрощает сопровождение проекта одним разработчиком. Событийная модель Node.js хорошо подходит для нагрузки интернет-банка, состоящей из множества коротких запросов к базе данных. Каркас Express выбран как минималистичный и самый распространённый для Node.js. Он даёт маршрутизацию и цепочку промежуточных обработчиков, не навязывая структуру приложения. Контроль типов обеспечивается аннотациями JSDoc, которые проверяются редактором без компиляции и не нарушают требование использовать именно JavaScript.')
    b.text('В качестве системы управления базами данных используется MySQL 8 с подсистемой хранения InnoDB. Для банковской предметной области определяющими являются транзакции, блокировки на уровне строк и ссылочная целостность. Каждая денежная операция выполняется в одной транзакции с уровнем изоляции READ COMMITTED и явными блокировками SELECT FOR UPDATE, внешние ключи защищают связи между счетами, документами и проводками, а триггеры запрещают изменение и удаление проводок и записей журнала аудита. Схема базы данных ведётся в виде пронумерованных SQL-файлов без ORM, тот же набор файлов служит листингом SQL-скрипта создания базы данных в приложении к записке. Доступ к базе данных выполняет драйвер mysql2 с параметризованными запросами.')
    b.text('Клиентская часть построена на HTML5, CSS3 и JavaScript без каркасов и шаблонизаторов. Интерфейс собирается в браузере модулями JavaScript. Сервер отдаёт статические файлы и данные в формате JSON, а переходы между страницами выполняет собственный маршрутизатор на основе History API. Такое решение удовлетворяет требованию единой каскадной таблицы стилей на всё приложение и не требует сборщика.')
    b.text('На сервере применяются внешние библиотеки express-session для сессий, bcrypt для хэширования паролей, helmet для защитных HTTP-заголовков, express-rate-limit для ограничения частоты запросов, nodemailer для отправки писем, pdfkit для документов PDF, qrcode для QR-кода настройки двухфакторной защиты. Автоматические тесты выполняются средствами Vitest и supertest на отдельной тестовой базе данных.')

    # 2.3 ------------------------------------------------------------------
    b.h2('2.3 Архитектурные решения')
    b.unit('func', [
        'Функционально программное средство делится на подсистемы, каждая из которых отвечает за одну область работы банка. Подсистемы регистрации, счетов, переводов, платежей, вкладов, кредитов и карт обслуживают клиентов, подсистемы антифрода, администрирования и отчётов используются сотрудниками банка, а безопасность, журнал аудита и уведомления являются общими для всех.',
        'Все подсистемы работают с единой базой данных и единым сервисом двойной записи, поэтому деньги, перемещённые одной подсистемой, сразу видны в остальных. Подсистемы не обращаются к таблицам друг друга напрямую и вызывают только сервисы других модулей, что позволяет изменять одну подсистему, не затрагивая остальные.',
    ], 'fig-func-arch.png', 'Функциональная архитектура программного средства')
    b.unit('arch', ['Приложение имеет клиент-серверную архитектуру. Сервер предоставляет программный интерфейс по адресам /api и статические файлы интерфейса, любой другой адрес получает страницу-оболочку, внутри которой клиентский маршрутизатор сам выбирает страницу. Серверный код организован по предметным модулям, среди которых счета, переводы, платежи, вклады, кредиты, карты, антифрод, клиенты, уведомления и администрирование. Каждый модуль состоит из четырёх слоёв, выстроенных по шаблону проектирования MVC.'], 'fig-arch.png', 'Слои обработки запроса на примере модуля переводов')
    b.text('Запрос из браузера сначала проходит общие промежуточные обработчики, которые загружают сессию, проверяют токен CSRF, загружают пользователя с правами его роли и контролируют обязательную двухфакторную защиту сотрудников. Маршрут связывает адрес и метод HTTP с обработчиком и проверяет право доступа, причём проверяется код права, а не название роли, так как набор прав закреплён за ролью в базе данных. Контроллер разбирает параметры запроса и формирует ответ JSON, не содержа бизнес-логики. Сервис реализует бизнес-правила и управляет транзакциями, модель выполняет SQL-запросы с параметрами. Зависимости направлены в одну сторону. Контроллеры не пишут SQL, модели не знают про HTTP, поэтому бизнес-логику можно проверять автотестами без веб-слоя.')
    b.text('Денежное ядро построено на принципе двойной записи. Каждая денежная операция оформляется документом с набором проводок «дебет – кредит – сумма», остаток счёта равен обороту по кредиту за вычетом оборота по дебету. Сервис двойной записи выполняет проводки документа в одной транзакции. Он блокирует задействованные счета в порядке возрастания идентификаторов, что исключает взаимные блокировки, проверяет статусы счетов и достаточность средств с учётом зарезервированных сумм и отклоняет документ целиком при любой ошибке. Ключ идемпотентности защищает от повторного проведения при двойной отправке формы. Исправления выполняются только сторнированием, история операций не переписывается.')
    b.text('Операционное время системы задаёт банковская дата. Её сдвигает процедура закрытия операционного дня, которая начисляет проценты и закрывает вклады с наступившим сроком, списывает платежи по кредитам и начисляет пеню, выполняет автоплатежи, отправляет пакет клиринга в другие банки и завершается контролем оборотно-сальдовой ведомости, при котором сумма остатков всех счетов в каждой валюте должна быть нулевой. Каждая операция дня выполняется в отдельной точке сохранения транзакции, поэтому ошибка одного платежа не откатывает закрытие дня целиком.')
    b.text('Таким образом, выбранная архитектура разделяет ответственность между слоями, сосредоточивает все денежные изменения в одном сервисе двойной записи и делает поведение системы во времени управляемым через банковскую дату.')

    # 2.4 ------------------------------------------------------------------
    b.h2('2.4 Разработка и описание алгоритмов, реализующих бизнес-логику программного средства')
    b.text('Схемы алгоритмов наглядно показывают порядок действий и ветвления без обращения к исходному коду. Схемы выполнены по ГОСТ 19.701-90 и содержат процессы, предопределённые процессы, решения с выходами «Да» и «Нет», блоки ввода и вывода данных, границы циклов и соединители для переноса схемы на соседнюю колонку.')
    b.unit('transfer', [
        'Алгоритм перевода клиенту банка. Функции createTransfer, confirmTransfer и executeIntentIn модуля переводов отвечают за перевод денег другому клиенту банка. Алгоритм запускается, когда клиент отправляет форму перевода, и содержит наибольшее число проверок. В нём проверяются данные, суточный лимит, правила антифрода и код подтверждения, а затем выполняются проводки двойной записи.',
        'Сначала проверяются данные. Счёт списания должен принадлежать клиенту и быть открытым, номер счёта получателя проверяется по контрольным цифрам IBAN и ищется в банке, сумма должна быть положительной. Сумма пересчитывается в белорусские рубли по официальному курсу и сверяется с суточным лимитом, в который входят переводы другим клиентам и в другие банки за банковскую дату.',
        'Затем вычисляется оценка риска. Правила антифрода начисляют баллы за крупную сумму, первый перевод новому получателю, частые переводы за короткое время и крупный перевод нового клиента. Если сумма баллов достигает порога проверки, перевод задерживается. Сумма резервируется на счёте, случай попадает в очередь специалиста по финансовому мониторингу, и клиент получает сообщение о проверке. Если требуется подтверждение, клиенту отправляется одноразовый код, на ввод которого даётся пять минут и три попытки.',
        'Завершает алгоритм транзакция, в которой строки счетов блокируются, лимит и остаток проверяются повторно уже под блокировкой, выполняются проводки перевода и комиссии. Повторная проверка исключает превышение лимита двумя заявками, подтверждёнными одновременно. При любой ошибке клиент получает сообщение об ошибке, а перевод не выполняется.',
    ], 'fig-flow.png', 'Схема алгоритма перевода клиенту банка')
    b.text('Алгоритмы обслуживания кредитов и вкладов опираются на расчётные формулы. Ежемесячный платёж аннуитетного графика вычисляется по формуле (2.1):')
    i, n, one = r('i'), r('n'), r('1')
    b.formula(r('A=') + frac(r('S·i'), r('1−') + sup(paren(r('1+i')), r('−n'))) + r(','))
    b.where([(r('A'), 'ежемесячный платёж'), (r('S'), 'сумма кредита'), (r('i'), 'месячная ставка, равная годовой ставке, делённой на 1200'), (r('n'), 'срок кредита в месяцах')])
    b.text('Проценты каждого платежа начисляются на остаток долга, погашение долга равно разности платежа и процентов, последний платёж закрывает остаток полностью. При дифференцированном графике долг гасится равными долями, и платёж с номером k вычисляется по формуле (2.2):')
    b.formula(sub(r('A'), r('k')) + r('=') + frac(r('S'), r('n')) + r('+') + sub(r('O'), r('k−1')) + r('·i,'))
    b.where([(sub(r('A'), r('k')), 'платёж с номером k'), (sub(r('O'), r('k−1')), 'остаток долга перед этим платежом')])
    b.text('Проценты по вкладу начисляются за фактическое число дней периода по формуле (2.3):')
    b.formula(r('I=') + frac(r('B·r·d'), r('100·D')) + r(','))
    b.where([(r('I'), 'начисленные проценты'), (r('B'), 'остаток вклада'), (r('r'), 'годовая ставка, %'), (r('d'), 'число дней периода'), (r('D'), 'число дней в году (365 или 366)')])
    b.text('Период, захватывающий границу лет, считается по частям для каждого года. Пеня по просроченному платежу кредита начисляется за каждый день просрочки по формуле (2.4):')
    b.formula(r('P=') + frac(sub(r('S'), r('пр')) + r('·p·d'), r('100')) + r(','))
    b.where([(r('P'), 'пеня'), (sub(r('S'), r('пр')), 'сумма просроченного платежа'), (r('p'), 'ставка пени за день, по умолчанию 0,1 %'), (r('d'), 'число дней просрочки')])
    b.text('Скоринг кредитной заявки выполняет модель логистической регрессии, обученная на истории выдач. Вероятность дефолта вычисляется по формуле (2.5):')
    b.formula(r('PD=') + frac(one, r('1+') + sup(r('e'), r('−(') + sub(r('w'), r('0')) + r('+') + sub(r('w'), r('1')) + sub(r('x'), r('1')) + r('+…+') + sub(r('w'), r('m')) + sub(r('x'), r('m')) + r(')'))) + r(','))
    b.where([(r('PD'), 'вероятность дефолта'), (sub(r('x'), r('j')), 'нормированные признаки заявки (возраст, доход, обязательства, доля платежа в доходе, стаж, иждивенцы, сумма)'), (sub(r('w'), r('j')), 'веса признаков, подобранные градиентным спуском')])
    b.text('При вероятности дефолта не выше 8 % и сумме в пределах лимита заявка одобряется автоматически, при вероятности до 30 % направляется кредитному специалисту, выше – отклоняется. Независимо от скоринга заявка отклоняется, если ежемесячные платежи превышают 40 % дохода. Все вычисления ведутся в копейках с округлением до ближайшей копейки, половина копейки округляется вверх.')
    b.unit('loans', [
        'Алгоритм обслуживания кредитов при закрытии операционного дня. Функция processLoans модуля кредитов вызывается процедурой закрытия дня и списывает плановые платежи по всем активным кредитам. Алгоритм состоит из двух вложенных циклов. Внешний цикл перебирает активные кредиты, внутренний перебирает их платежи со сроком не позже новой банковской даты.',
        'По уже просроченному платежу сначала начисляется пеня за прошедшие дни. Платежи гасятся строго по порядку графика. Если ранний платёж не оплачен или на счёте клиента не хватает денег, текущий платёж отмечается просроченным и более поздние не списываются. Иначе проводками списываются долг, проценты и пеня, а платёж отмечается оплаченным. Если после обработки платежей у кредита не осталось долга, закрываются кредит и ссудный счёт, затем сохраняются остаток долга и дата последней оплаты.',
    ], 'fig-flow-loans.png', 'Схема алгоритма обслуживания кредитов при закрытии дня')
    b.unit('deposits', [
        'Алгоритм начисления процентов и возврата вкладов. Функция processDeposits модуля вкладов вызывается процедурой закрытия дня для всех активных вкладов, у которых наступила дата очередной выплаты. Каждый вклад обрабатывается в собственной точке сохранения транзакции, поэтому ошибка по одному вкладу (например, заблокированный счёт) не отменяет закрытие дня.',
        'Во внутреннем цикле обрабатываются все периоды, дата выплаты которых не позже банковской даты. За период рассчитываются проценты по фактическому числу дней. Если проценты больше нуля, при капитализации они зачисляются на счёт вклада и увеличивают базу следующего периода, иначе выплачиваются на текущий счёт клиента. Когда наступает срок вклада, остаток возвращается на текущий счёт, вклад и его счёт закрываются, иначе сохраняются дата и число обработанных периодов. При ошибке изменения вклада откатываются к точке сохранения, и вклад будет обработан при следующем закрытии дня.',
    ], 'fig-flow-deposits.png', 'Схема алгоритма начисления процентов и возврата вкладов')
    b.text('Таким образом, разработанные алгоритмы охватывают ключевые операции системы, а именно переводы с многоуровневым контролем, обслуживание кредитов и вкладов при закрытии дня и расчёты по продуктам.')

    # 2.5 ------------------------------------------------------------------
    b.h2('2.5 Проектирование пользовательского интерфейса')
    b.text('Интерфейс спроектирован по макетам, подготовленным до вёрстки, и опирается на приёмы действующих банковских сайтов. Это светлая страница, крупные скруглённые плитки разделов, двухэтажная шапка с утилитарной полосой и меню, чипы-переключатели и талоны-квитанции для результатов операций. Все стили собраны в единственной каскадной таблице, встроенные стили запрещены политикой безопасности содержимого. Цвета заданы переменными CSS, тёмная тема переопределяет переменные и включается переключателем в шапке либо по системной настройке. Основной шрифт – Golos Text с табличными цифрами, чтобы суммы в колонках выравнивались по разрядам.')
    b.text('Все страницы имеют общую структуру. Двухэтажная шапка состоит из утилитарной полосы (роль пользователя, курсы валют, поиск, переключатель темы, безопасность, уведомления с числом непрочитанных и короткий номер банка) и основной полосы с логотипом, меню разделов и кнопкой выхода. Меню строится по правам роли. Клиент видит счета и карты, платежи и переводы, вклады и кредиты, сотрудник – разделы своего рабочего места. Поиск открывается панелью поверх страницы и находит действия, услуги каталога и собственные счета клиента по первым буквам.')
    b.text('Формы приложения подключаются общим помощником, который блокирует повторную отправку, показывает ошибки сервера у конкретных полей, а для необратимых действий (закрыть счёт, закрыть карту, удалить шаблон, закрыть операционный день) требует подтверждения прямо в форме.')
    b.text('Интерфейс учитывает требования доступности. Все действия выполняются с клавиатуры, видимый фокус не скрывается, после перехода фокус переводится на содержимое страницы, выбранные элементы отмечены атрибутами ARIA, контраст текста в обеих темах подобран по рекомендациям WCAG. Анимации используются только там, где сообщают о состоянии, и отключаются при системной настройке уменьшения движения. Вёрстка адаптируется к ширине экрана телефона без горизонтальной прокрутки.')
    b.unit('cabinet', [
        'После входа клиент попадает в кабинет. Вверху выводятся сумма по счетам в национальной валюте, кнопки частых действий и напоминание о ближайшем платеже по кредиту, ниже – плитки продуктов с объёмными значками, последние операции и курсы валют.',
        'Каждая страница является модулем JavaScript, который запрашивает данные программного интерфейса и возвращает разметку. Разметка собирается шаблонной функцией с автоматическим экранированием подстановок, что исключает внедрение разметки через данные. Внизу всех страниц находится подвал с разделами продуктов, информацией и контактами банка.',
    ], 'fig-ui-cabinet.png', 'Главная страница кабинета клиента')
    b.unit('transfer-ui', [
        'Форма перевода построена по образцу мобильных банков. Вкладки выбирают вид перевода, счета списания и зачисления выбираются из списков с остатками, сумма вводится крупным полем. Под формой показываются комиссия и сумма к зачислению, а при переводе между счетами в разных валютах – курс конвертации.',
        'Если перевод требует подтверждения, открывается отдельный экран ввода одноразового кода с таймером срока действия и числом оставшихся попыток. В учебном режиме без почтового сервера код показывается прямо на этом экране, при настроенной почте он приходит письмом. После проведения перевода клиент видит квитанцию с реквизитами операции.',
    ], 'fig-ui-transfer.png', 'Форма перевода')
    b.unit('deposit-ui', [
        'Оформление вклада совмещено с калькулятором. Ползунок суммы и выбор продукта сразу пересчитывают доход за срок, который показывается на итоговом талоне справа. Расчёт выполняет сервер по той же функции, что и начисление процентов, поэтому клиент видит точную сумму, которую получит.',
        'Со страницы открытого вклада доступно досрочное закрытие. Перед подтверждением система показывает расчёт процентов по ставке до востребования, уже выплаченные проценты и сумму к возврату, поэтому клиент заранее видит, сколько получит. Закрытие выполняется только после явного подтверждения в форме.',
    ], 'fig-ui-deposit.png', 'Оформление вклада')
    b.unit('statement', [
        'Выписка оформлена в виде бумажного талона с перфорацией. Вверху показаны входящий и исходящий остатки, ниже операции, сгруппированные по дням, внизу итоги за период и кнопка скачивания PDF. Чипы над талоном переключают счёт, быстрые периоды и вид операций, свой период задаётся датами.',
        'Документы PDF (выписка, справка об остатке, квитанции платежей) формирует сервер библиотекой pdfkit со встроенным шрифтом с кириллицей. Ссылка на документ ведёт прямо на адрес программного интерфейса, и браузер скачивает файл, а данные в документе совпадают с показанными на странице, потому что берутся из тех же сервисов.',
    ], 'fig-ui-statement.png', 'Выписка по счёту')
    b.unit('workplace', [
        'Сотрудники банка работают в том же приложении, но видят другое меню и другую главную страницу – рабочее место. Набор пунктов меню и показателей строится по правам роли. Операционист видит очередь анкет, кассу и блокировку счетов, кредитный специалист – очередь заявок на кредит, специалист по мониторингу – задержанные переводы, администратор – курсы и тарифы, пользователей, журнал аудита, отчёты, резервные копии и закрытие дня.',
        'На рабочем месте выводятся плитки показателей по правам роли (анкеты на проверке, кассовые операции за день, заблокированные счета) и список ближайших задач с переходом к нужной карточке. Сотрудник видит только те показатели и задачи, к которым у его роли есть доступ.',
        'Анкету нового клиента операционист открывает из очереди. Паспортные данные и идентификационный номер расшифровываются только на время просмотра, а сам просмотр записывается в журнал аудита. Подтверждение анкеты сразу открывает клиенту текущий счёт в белорусских рублях, отказ требует указать причину. На этом же рабочем месте выполняются взнос и выдача наличных через кассу и блокировка счёта по основанию, например по решению суда.',
    ], 'fig-ui-workplace.png', 'Рабочее место операциониста')
    b.unit('loan-review', [
        'Очереди сотрудников оформлены списками с кратким описанием каждого элемента, а карточка элемента показывает все данные для решения и кнопки решения в одном месте. В карточке заявки на кредит выводятся данные клиента, параметры кредита, вероятность дефолта по модели скоринга, долговая нагрузка и график платежей.',
        'Решение принимается кнопками «Одобрить» и «Отклонить», при отказе обязательно указывается причина, которая уходит клиенту в уведомлении. Каждое решение записывается в журнал аудита с указанием сотрудника, поэтому его можно проверить позднее.',
        'Вероятность дефолта выводится вместе с вкладом каждого признака заявки в итоговую оценку модели, поэтому специалист видит, повлияли ли на решение низкий доход, высокая долговая нагрузка или короткий стаж. Это позволяет обосновать одобрение или отказ, а не опираться только на итоговое число.',
    ], 'fig-ui-loan-review.png', 'Карточка заявки на кредит')
    b.text('Таким образом, интерфейс выдержан в едином стиле для всех ролей, а различия между клиентом и сотрудниками определяются только правами роли.')

    # 2.6 ------------------------------------------------------------------
    b.h2('2.6 Методы обеспечения безопасности данных')
    b.text('Банковская система хранит персональные данные клиентов и управляет их деньгами, поэтому защита построена в несколько уровней. Каждый уровень закрывает свой класс угроз, и обход одного уровня не даёт злоумышленнику доступа к данным, так как запрос проходит и остальные проверки.')
    b.unit('security', [
        'Первый уровень защищает передачу данных. Браузер обращается к серверу по протоколу HTTPS, поэтому пароли, коды и данные операций передаются в зашифрованном виде. Промежуточный обработчик helmet выставляет защитные заголовки HTTP, а политика безопасности содержимого разрешает загрузку скриптов и стилей только с адреса самого приложения, что препятствует внедрению чужого кода в страницы. Идентификатор сессии передаётся в cookie с флагом httpOnly, поэтому сценарии на странице не могут его прочитать, а флаг SameSite не позволяет другим сайтам отправлять запросы от имени пользователя.',
    ], 'fig-security.png', 'Уровни защиты программного средства')
    b.text('Второй уровень отвечает за доступ к системе. Пароли хранятся только в виде хэшей bcrypt с коэффициентом стоимости 12, поэтому даже при утечке базы данных исходные пароли восстановить практически невозможно. После пяти неверных попыток учётная запись блокируется на 15 минут, а частота запросов входа и регистрации с одного адреса ограничена. Счётчик неудачных попыток сбрасывается только после полностью завершённого входа, включая второй фактор, поэтому знание пароля не открывает возможности перебирать коды.')
    b.text('Двухфакторная защита реализована по стандарту TOTP (RFC 6238). Приложение-аутентификатор на телефоне пользователя каждые 30 секунд вычисляет новый шестизначный код, сервер принимает каждый код только один раз, а на случай потери телефона при настройке выдаются десять одноразовых резервных кодов. Для сотрудников банка двухфакторная защита обязательна, и её включение требует повторного ввода пароля.')
    b.text('Сессия хранится на сервере в базе данных. При входе идентификатор сессии и токен защиты от подделки межсайтовых запросов (CSRF) создаются заново, сессия завершается после 30 минут бездействия и в любом случае через восемь часов после входа. Каждый запрос, изменяющий данные, обязан передать токен CSRF в заголовке, иначе он отклоняется. Права доступа проверяются на сервере по набору прав роли, поэтому скрытая в интерфейсе кнопка не открывает доступа к операции.')
    b.text('Третий уровень контролирует сами операции. Сервер проверяет все входные данные независимо от проверок в браузере, в том числе числовые идентификаторы, допустимые значения справочников и длину строк, а все запросы к базе данных выполняются с параметрами, что исключает внедрение SQL-кода. Денежные операции подтверждаются одноразовым кодом со сроком действия пять минут и тремя попытками ввода. Подозрительные переводы задерживаются антифродом до решения специалиста, суточный лимит ограничивает возможный ущерб, а транзакции с блокировкой строк исключают двойное списание при одновременных запросах.')
    b.text('Четвёртый уровень защищает хранимые данные. Серия и номер паспорта, идентификационный номер и секрет двухфакторной защиты шифруются алгоритмом AES-256-GCM, который вместе с шифрованием проверяет целостность данных. Для поиска дубликатов по зашифрованному полю хранится отдельный ключевой хэш HMAC-SHA-256, поэтому расшифровывать данные для проверки не требуется. Ключ шифрования хранится отдельно от базы данных в настройках сервера.')
    b.text('Все значимые действия записываются в журнал аудита с указанием пользователя, времени, адреса и результата. Триггеры базы данных запрещают изменение и удаление записей журнала и проводок, поэтому историю операций нельзя переписать даже с правами администратора. Резервная копия базы данных создаётся по расписанию утилитой mysqldump и сразу шифруется ключом приложения. При восстановлении из копии записи журнала аудита, сделанные после её создания, сохраняются, а все сеансы пользователей завершаются.')
    b.text('Таким образом, принятые меры обеспечивают шифрование хранимых и передаваемых данных, разграничение прав по ролям, контроль целостности операций и резервное копирование, а работа механизмов защиты проверяется автоматическими тестами вместе с бизнес-логикой.')

    b.save(out)


